<template>
 <section class="combat-social" data-social-surface data-combat-social @pointerdown.stop @click.stop @keydown.stop @keyup.stop aria-label="Messages et notifications pendant le combat">
  <header><journal-icon name="messages"/><label class="sr-only" for="combat-social-peer">Choisir une conversation</label><select id="combat-social-peer" v-model="selected" data-combat-peer><option value="inbox">Notifications{{ state.incoming.length?' · '+state.incoming.length:'' }}</option><option v-for="p in friends" :key="p.id" :value="String(p.id)">{{ p.username }}{{ p.afk?' · AFK':'' }}{{ p.unread?' · '+p.unread+' non lu'+(p.unread>1?'s':''):'' }}</option></select><button aria-label="Réduire les messages" data-close-combat-chat @click="$emit('close')">×</button></header>
  <private-chat v-if="friend" :key="friend.id" compact :friend="friend" :user-id="userId" :connected="connected" :incoming-message="incomingMessage" :command="command" :saved-draft="drafts[friend.id]||''" @draft="$emit('draft',$event)" @reading="$emit('reading',$event)"/>
  <div v-else class="combat-inbox"><p v-if="!connected" role="status">Connexion interrompue.</p><p v-if="error" role="alert">{{ error }}</p><article v-for="p in state.incoming" :key="p.id"><span><b>{{ p.username }}</b> veut t’ajouter en ami.</span><button :disabled="busy||!connected" :data-combat-accept="p.id" @click="answer(p.id,'accept')">Accepter</button><button :disabled="busy||!connected" @click="answer(p.id,'decline')">Refuser</button></article><p v-if="tradeInvite">Un ami te propose un échange. Tu pourras le rejoindre après le combat.</p><p v-if="!state.incoming.length&&!tradeInvite">{{ friends.length?'Choisis un ami pour lire ou envoyer un message.':'Aucune nouvelle notification. Tes amis apparaîtront ici.' }}</p></div>
 </section>
</template>
<script>
import JournalIcon from '../menu/JournalIcon.vue';
import PrivateChat from './PrivateChat.vue';
export default{components:{JournalIcon,PrivateChat},props:{state:Object,userId:Number,connected:Boolean,incomingMessage:Object,command:Function,drafts:Object,initialTarget:[String,Number],tradeInvite:Object},data(){return{selected:String(this.state.accepted.find(p=>String(p.id)===String(this.initialTarget))?.id||this.state.accepted.find(p=>p.unread)?.id||'inbox'),busy:false,error:''};},computed:{friends(){return [...this.state.accepted].sort((a,b)=>Number(b.unread>0)-Number(a.unread>0)||a.username.localeCompare(b.username,'fr'));},friend(){return this.state.accepted.find(p=>String(p.id)===this.selected);}},mounted(){this.$emit('target',this.selected);},watch:{selected(value){this.$emit('target',value);},'state.accepted'(){if(this.selected!=='inbox'&&!this.friend)this.selected='inbox';}},beforeDestroy(){this.$emit('reading',null);},methods:{async answer(targetId,action){if(this.busy)return;this.busy=true;this.error='';try{await this.command('social:friend',{targetId,action});}catch(e){this.error=e.message;}finally{this.busy=false;}}}};
</script>
<style scoped>
.combat-social{height:100%;min-height:0;display:flex;flex-direction:column;border:1px solid var(--journal-border);border-radius:10px;background:var(--journal-paper);color:var(--journal-ink);font:12px var(--journal-font);overflow:hidden}header{display:flex;align-items:center;gap:6px;padding:3px 6px;border-bottom:1px solid var(--journal-border);flex:none;background:var(--journal-card)}header>.journal-icon{width:16px;height:16px;color:var(--journal-accent)}header select{flex:1;min-width:0;width:100%;height:28px;padding:1px 4px;border:0;border-radius:5px;background:var(--journal-card);color:var(--journal-heading);font:600 11px var(--journal-font)}header button{min-width:32px;min-height:30px;padding:0;border:1px solid var(--journal-border);border-radius:7px;background:var(--journal-card);color:var(--journal-ink);font-size:19px;cursor:pointer}.combat-inbox{padding:5px 10px;overflow:auto;min-height:0;flex:1}.combat-inbox p{margin:5px 0;font-size:11px;color:var(--journal-muted)}.combat-inbox article{display:flex;align-items:center;flex-wrap:wrap;gap:6px;padding:5px 0;font-size:11px}.combat-inbox article span{flex:1;min-width:120px}.combat-inbox button{min-height:32px;padding:5px 7px;border:1px solid var(--journal-border);border-radius:6px;background:var(--journal-card);color:var(--journal-ink);font:11px var(--journal-font);cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;clip:rect(0,0,0,0);overflow:hidden}.combat-social :focus-visible{outline:2px solid var(--journal-accent);outline-offset:-2px}
</style>
